/* From Uiverse.io by andrew-demchenk0 - Tags: blue, button, refresh */
.__UIV_SCOPE__ .button {
  position: relative;
  width: 150px;
  height: 40px;
  cursor: pointer;
  display: flex;
  align-items: center;
  border: 1px solid #0078E8;
  background-color: #0082FC;
  overflow: hidden;
}

.__UIV_SCOPE__ .button, .__UIV_SCOPE__ .button__icon, .__UIV_SCOPE__ .button__text {
  transition: all 0.3s;
}

.__UIV_SCOPE__ .button .button__text {
  transform: translateX(30px);
  color: #fff;
  font-weight: 600;
}

.__UIV_SCOPE__ .button .button__icon {
  position: absolute;
  transform: translateX(109px);
  height: 100%;
  width: 39px;
  background-color: #0078E8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .button .svg {
  width: 20px;
  fill: #fff;
}

.__UIV_SCOPE__ .button:hover {
  background: #0078E8;
}

.__UIV_SCOPE__ .button:hover .button__text {
  color: transparent;
}

.__UIV_SCOPE__ .button:hover .button__icon {
  width: 148px;
  transform: translateX(0);
}

.__UIV_SCOPE__ .button:active .button__icon {
  background-color: #006cd0;
}

.__UIV_SCOPE__ .button:active {
  border: 1px solid #006cd0;
}
